p=pathlib.Path('visual-lab/landscape-color-grammar.json');v=json.loads(p.read_text());v['rules'].append({'id':'LC-hybrid-ground-attachment','principle':'Match ground and vegetation at contact while separating the texture projection suitable for each surface.','referenceEvidence':[{'source':'visual-lab/feedback/hybrid-grass-direction.json','observation':'User identifies vertical bands and root-to-ground mismatch, and requests a shorter brush layer with sparse tall accents.'}],'implementationHypothesis':'Share world-space pigments and root texture values; fade terrain texture detail and atlas tint by actual height above planted root, using atlas strokes above that zone.','renderEvidence':['artifacts/hybrid-grass/band-diagnosis.png','artifacts/hybrid-grass/comparison.png'],'result':'Diagnostic removal of projected map detail largely removes bands; flattening normals does not. World-height root blending and shorter grass substantially reduce visible streak walls.','knownLimitations':'Only this savanna shader/seed29 tested; low alpha boundaries and sloped ground contact remain imperfect. Root height is relative to the planted anchor, not full per-fragment terrain conformance.','constraints':{'universalPrinciple':'Projection and contact coherence apply widely;6-30cm ranges and golden pigments are experiment-specific.','biome':['savanna'],'otherBiomes':'Not modified or tested by this experiment.'},'status':'experimentally-supported','humanApproval':None});p.write_text(json.dumps(v,indent=2)+'\n')
